import type { LngLatBounds } from '@maplibre/maplibre-react-native';

/** [west, south, east, north] */
export type OfflineBounds = LngLatBounds;

export type OfflineRegionStatus =
  | 'pending'
  | 'downloading'
  | 'paused'
  | 'completed'
  | 'failed'
  | 'missing';

export interface OfflineRegion {
  id: string;
  /** ID generated by MapLibre when the native pack is created. */
  packId: string | null;
  name: string;
  bounds: OfflineBounds;
  minZoom: number;
  maxZoom: number;
  styleUrl: string;
  status: OfflineRegionStatus;
  /** Percentage from 0 to 100. */
  progress: number;
  completedResourceCount: number;
  requiredResourceCount: number;
  /** Bytes reported by MapLibre for the downloaded resources. */
  sizeBytes: number;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface CreateOfflineRegionInput {
  /**
   * Optional caller-supplied record ID. The combined offline-regions feature
   * uses one ID for both the MapLibre pack and the routing package.
   */
  id?: string;
  name: string;
  bounds: OfflineBounds;
  minZoom: number;
  maxZoom: number;
}

export interface StyleCapabilities {
  styleUrl: string;
  minZoom: number;
  maxZoom: number;
  hasGlyphs: boolean;
  hasSprite: boolean;
  warnings: string[];
}

export interface StorageInfo {
  availableBytes: number | null;
  totalBytes: number | null;
  downloadedBytes: number;
}

export interface OfflineVerificationResult {
  ok: boolean;
  message: string;
  region: OfflineRegion;
}

export type OfflineMapsErrorCode =
  | 'unsupported'
  | 'offline'
  | 'invalid_bounds'
  | 'invalid_zoom'
  | 'duplicate'
  | 'storage'
  | 'permission'
  | 'style_resources'
  | 'download_failed'
  | 'pack_missing'
  | 'unknown';

export class OfflineMapsError extends Error {
  readonly code: OfflineMapsErrorCode;

  constructor(code: OfflineMapsErrorCode, message: string, options?: { cause?: unknown }) {
    super(message);
    this.name = 'OfflineMapsError';
    this.code = code;
    if (options && 'cause' in options) {
      this.cause = options.cause;
    }
  }
}

export function toOfflineMapsError(error: unknown): OfflineMapsError {
  if (error instanceof OfflineMapsError) {
    return error;
  }

  if (error instanceof Error) {
    return new OfflineMapsError('unknown', error.message || 'Something went wrong.', {
      cause: error,
    });
  }

  return new OfflineMapsError('unknown', 'Something went wrong.', { cause: error });
}
